  remove(subscriber: string) {
    const count = this.rules.length;
    this.rules = this.rules.filter((rule) => rule.subscriber !== subscriber);
    return count - this.rules.length;
  }
  topics() {
    return [...new Set(this.rules.flatMap((rule) => [...rule.topics]))].sort();
